export declare const whitespaceGalleryTheme = "/* \u7559\u767D\u753B\u518C\uFF1A\u56FE\u7247\u4E0E\u4EBA\u7269\u6545\u4E8B */\n#wemd {\n  max-width: 677px;\n  margin: 0 auto;\n  padding: 30px 24px;\n  color: #3a3734;\n  background-color: transparent;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 17px;\n  line-height: 2;\n  letter-spacing: 0.035em;\n  word-break: break-word;\n}\n\n#wemd p {\n  max-width: 34em;\n  margin: 0 auto 31px;\n  color: #3a3734;\n  font-size: 17px;\n  line-height: 2;\n  text-align: left;\n  text-wrap: pretty;\n}\n\n#wemd h1 {\n  max-width: 12em;\n  margin: 58px auto 96px;\n  padding: 0;\n  border: none;\n  text-align: center;\n}\n\n#wemd h1 .content {\n  color: #2b2927;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 38px;\n  font-weight: 700;\n  line-height: 1.42;\n  letter-spacing: 0.08em;\n  text-wrap: balance;\n}\n\n#wemd h2 {\n  max-width: 22em;\n  margin: 78px auto 34px;\n  text-align: left;\n}\n\n#wemd h2 .content {\n  display: block;\n  padding: 0;\n  border: none;\n  color: #2b2927;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 26px;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  text-wrap: balance;\n}\n\n#wemd h3 {\n  max-width: 34em;\n  margin: 44px auto 20px;\n  padding: 0;\n  border: none;\n}\n\n#wemd h3 .content {\n  color: #80503f;\n  font-size: 15px;\n  font-weight: 700;\n  letter-spacing: 0.12em;\n  text-wrap: balance;\n}\n\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  max-width: 40em;\n  margin: 30px auto 15px;\n}\n\n#wemd h4 .content,\n#wemd h5 .content,\n#wemd h6 .content {\n  color: #625b55;\n  font-size: 16px;\n  font-weight: 650;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix,\n#wemd h2 .prefix,\n#wemd h2 .suffix,\n#wemd h3 .prefix,\n#wemd h3 .suffix,\n#wemd h4 .prefix,\n#wemd h4 .suffix,\n#wemd h5 .prefix,\n#wemd h5 .suffix,\n#wemd h6 .prefix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 62px 0;\n  padding: 38px 28px;\n  border: none;\n  background: #2b2927;\n  break-inside: avoid;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0 auto;\n  color: #f7f6f4;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 21px;\n  line-height: 1.85;\n  letter-spacing: 0.04em;\n  text-align: center;\n}\n\n#wemd .multiquote-2,\n#wemd .multiquote-3,\n#wemd .multiquote-1 .multiquote-1 {\n  margin: 18px 0 0;\n  padding: 14px 0 0;\n  border: none;\n  border-top: 1px solid #77716c;\n  background: transparent;\n}\n\n#wemd ul,\n#wemd ol {\n  max-width: 38em;\n  margin: 24px auto 31px;\n  padding-left: 25px;\n  color: #8b4c3b;\n}\n\n#wemd li section {\n  margin: 7px 0;\n  color: #3a3734;\n  line-height: 1.85;\n}\n\n#wemd ol > li > section {\n  padding-bottom: 4px;\n  border: none;\n}\n\n#wemd a {\n  color: #80503f;\n  font-weight: 600;\n  text-decoration: underline;\n  text-underline-offset: 0.23em;\n}\n\n#wemd strong {\n  color: #2b2927;\n  font-weight: 750;\n}\n\n#wemd mark {\n  padding: 1px 4px;\n  color: #4c382f;\n  background: #eadbd5;\n}\n\n#wemd hr {\n  width: 1px;\n  height: 64px;\n  margin: 72px auto;\n  border: none;\n  background: #2b2927;\n}\n\n#wemd figure {\n  margin: 72px 0 80px;\n  break-inside: avoid;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd img,\n#wemd figure a img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n}\n\n#wemd figcaption {\n  max-width: 34em;\n  margin: 16px auto 0;\n  padding-top: 9px;\n  border-top: 1px solid #bbb6b1;\n  color: #77706a;\n  font-size: 12px;\n  line-height: 1.7;\n  letter-spacing: 0.055em;\n  text-align: left;\n}\n\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  padding: 2px 5px;\n  border-bottom: 1px solid #a7a29d;\n  color: #5c4740;\n  background: #f3f2f1;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n}\n\n#wemd pre {\n  margin: 38px 0;\n  border: 1px solid #2b2927;\n  background: #2b2927;\n  overflow-x: auto;\n}\n\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  min-width: max-content;\n  padding: 21px;\n  color: #f0efed;\n  background: #2b2927;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  line-height: 1.72;\n  white-space: pre;\n}\n\n#wemd pre.custom > .mac-sign {\n  display: block;\n  border-bottom: 1px solid #57524e;\n  background: #2b2927;\n}\n\n#wemd .table-container {\n  margin: 39px 0;\n  overflow-x: auto;\n}\n\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  color: #3a3734;\n  background: transparent;\n  text-align: left;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  min-width: 88px;\n  padding: 11px 9px;\n  border: none;\n  border-bottom: 1px solid #bbb6b1;\n  font-size: 14px;\n  line-height: 1.65;\n}\n\n#wemd table tr th {\n  border-top: 3px solid #2b2927;\n  border-bottom: 2px solid #2b2927;\n  color: #2b2927;\n  background: transparent;\n  font-weight: 750;\n}\n\n#wemd table tr:nth-child(2n) {\n  background: transparent;\n}\n\n#wemd .callout {\n  max-width: 34em;\n  margin: 52px auto;\n  padding: 24px 0;\n  border: none;\n  border-top: 1px solid #aaa49f;\n  border-bottom: 1px solid #aaa49f;\n  border-radius: 0;\n  color: #49433f;\n  background: transparent;\n  break-inside: avoid;\n}\n\n#wemd .callout-warning,\n#wemd .callout-caution {\n  border-color: #8b4c3b;\n  background: transparent;\n}\n\n#wemd .callout-title {\n  margin-bottom: 8px;\n  color: #2b2927;\n  font-weight: 700;\n}\n\n#wemd .callout p {\n  margin: 0;\n  color: #5e5751;\n  font-size: 15px;\n}\n\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #80503f;\n  font-weight: 700;\n}\n\n#wemd .footnotes-sep {\n  margin-top: 57px;\n  padding-top: 18px;\n  border-top: 1px solid #2b2927;\n}\n\n#wemd .footnote-item {\n  display: flex;\n  max-width: 40em;\n  margin: 10px auto 0;\n}\n\n#wemd .footnote-num {\n  width: 30px;\n  flex-shrink: 0;\n  color: #80503f;\n}\n\n#wemd .footnote-item p {\n  margin: 0;\n  color: #77706a;\n  font-size: 13px;\n  text-align: left;\n}\n\n#wemd .block-equation {\n  display: block;\n  margin: 38px 0;\n  padding: 20px 10px;\n  border-top: 1px solid #bbb6b1;\n  border-bottom: 1px solid #bbb6b1;\n  text-align: center;\n  overflow-x: auto;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n}\n\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n#wemd pre.mermaid {\n  padding: 22px 10px;\n  border: 1px solid #aaa49f;\n  border-top: 4px solid #2b2927;\n  background: #ffffff;\n}\n\n#wemd .task-list-item {\n  display: flex;\n  align-items: flex-start;\n  margin-left: -1.2em;\n  list-style: none;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 8px;\n  margin-right: 8px;\n  accent-color: #2b2927;\n  pointer-events: none;\n}\n";
